mapper.select:
SELECT t.*, a.account_no AS accountNo, b.account_no AS targetAccountNo, u.user_name AS counterUserName FROM trade_record t LEFT JOIN account a ON a.account_id=t.account_id LEFT JOIN account b ON b.account_id=t.target_account_id LEFT JOIN `user` u ON u.user_id=t.counter_user_id
AND a.user_id = #{userId}
AND t.trade_no LIKE CONCAT('%', #{tradeNo}, '%')
AND a.account_no LIKE CONCAT('%', #{accountNo}, '%')
AND t.trade_type = #{tradeType}
AND t.trade_status = #{tradeStatus}
ORDER BY t.trade_id ASC
